int binarySearch(const vector<int>& arr, int target) {
    int l = 0;
    int r = static_cast<int>(arr.size()) - 1; // last valid index

    while (l <= r) {
        int mid = l + (r - l) / 2; // safe midpoint
        if (arr[mid] == target) {
            return mid;
        } else if (arr[mid] < target) {
            l = mid + 1;
        } else {
            r = mid - 1; // shrink right bound
        }
    }
    return -1;
}

